#pragma once

#include "Core/JamTypes.h"
#include "CoreMinimal.h"
#include "Sim/JamLayerRules.h"

/** The rich effects of the full-art tier (T-069), by what they show; the view maps each to a Niagara system. */
enum class EJamFx : uint8
{
	Sparks,
	Dust,
	Cash
};

/** One effect to start this frame: where, how big, in which colour. */
struct FJamFxCue
{
	EJamFx Kind = EJamFx::Sparks;
	FVector2D Pos = FVector2D::ZeroVector;
	/** Height above the floor, cm. */
	float Height = 0.f;
	FLinearColor Color = FLinearColor::White;
	/** Sparks: how big the burst is, 1 for a plain hit. Dust: the radius it reaches, cm. */
	float Size = 1.f;
};

/**
 * How the hero's Ultimate charge and his dash show, by the look the cuts left (T-072): an aura on the 3D hero and the
 * afterimages alone; a simpler glow on the floor under the shape ronin and a thin streak; the plain bars in greybox.
 */
enum class EJamChargeLook : uint8
{
	Aura,
	Glow,
	Bars
};

/** The charge aura on the hero (T-072): how big and how busy it is, and whether it says "ready". */
struct FJamAura
{
	bool bOn = false;
	/** Its size, 1 when the charge is full. */
	float Size = 0.f;
	/** Its particles a second. */
	float Rate = 0.f;
	bool bReady = false;
};

/**
 * Which rich effects a step of the fight starts (T-069). They belong to the full art: once the first cut took it,
 * nothing here starts, and the plain effects of the effects view carry the fight alone.
 * Tests: Jam.Fx.*
 */
namespace JamFxRules
{
/** Hero's and Publisher's colours, as the rest of the game paints them. */
inline const FLinearColor HeroNeon(0.3f, 0.95f, 1.0f);
inline const FLinearColor BossNeon(1.0f, 0.25f, 0.2f);
inline const FLinearColor BlastYellow(1.0f, 0.85f, 0.15f);
inline const FLinearColor UltimateMagenta(1.0f, 0.25f, 0.75f);
// Dark enough that the smoke does not white out the bodies under the bloom.
inline const FLinearColor DustGrey(0.4f, 0.4f, 0.45f);
inline const FLinearColor CashGreen(0.2f, 1.0f, 0.4f);

/** Appends the effects the step that made Events starts to Out; none when bArt is false. */
JAMGAME_API void CuesFor(const FJamFight& Fight, TConstArrayView<FJamEvent> Events, bool bArt, TArray<FJamFxCue>& Out);

/** The look of the charge and the dash for the layers on show. */
JAMGAME_API EJamChargeLook ChargeLook(const FJamLayers& Shown);

/**
 * The aura for an Ultimate meter of Meter (0 to 1): none until the hero owns the Ultimate, growing with the charge, a
 * clear step up when it is full, and its biggest while he winds the cut up.
 */
JAMGAME_API FJamAura Aura(float Meter, bool bOwns, bool bWindingUp);
} // namespace JamFxRules
#include "View/JamFxRules.h"

namespace
{
// Heights of the sparks: about the chest of each body; a blast or a slash at the hero's chest height.
constexpr float HeroChest = 120.f;
constexpr float BossChest = 160.f;
// A plain hit's damage: sparks of size 1; bigger hits throw bigger bursts, within these bounds.
constexpr float PlainHit = 14.f;
constexpr float SmallestSparks = 0.6f;
constexpr float BiggestSparks = 1.8f;
constexpr float BlastSparks = 1.5f;
constexpr float DeflectSparks = 1.f;
constexpr float UltimateSparks = 2.2f;
// The charge aura (T-072): its size and its particles a second from an empty meter to a nearly full one, then the step
// up when it is full, and the wind-up's flare.
constexpr float AuraLeastSize = 0.35f;
constexpr float AuraChargedSize = 0.7f;
constexpr float AuraLeastRate = 6.f;
constexpr float AuraChargedRate = 35.f;
constexpr float AuraReadySize = 1.f;
constexpr float AuraReadyRate = 90.f;
constexpr float AuraWindUpSize = 1.4f;
constexpr float AuraWindUpRate = 180.f;

FJamFxCue Cue(EJamFx Kind, const FVector2D& Pos, float Height, const FLinearColor& Color, float Size)
{
	FJamFxCue Out;
	Out.Kind = Kind;
	Out.Pos = Pos;
	Out.Height = Height;
	Out.Color = Color;
	Out.Size = Size;
	return Out;
}
} // namespace

void JamFxRules::CuesFor(const FJamFight& Fight, TConstArrayView<FJamEvent> Events, bool bArt, TArray<FJamFxCue>& Out)
{
	if (!bArt)
	{
		return;
	}
	for (const FJamEvent& Event : Events)
	{
		switch (Event.Type)
		{
			case EJamEvent::Hit:
			{
				// Sparks fly off the body that was hit, in the colour of the one who hit it.
				const bool bOnBoss = Event.Side == EJamSide::Boss;
				const float Size = FMath::Clamp(Event.Amount / PlainHit, SmallestSparks, BiggestSparks);
				Out.Add(Cue(
					EJamFx::Sparks, Fight.Fighters[Event.Side].Pos, bOnBoss ? BossChest : HeroChest, bOnBoss ? HeroNeon : BossNeon, Size));
				break;
			}
			case EJamEvent::Explosion:
				Out.Add(Cue(EJamFx::Sparks, Event.Pos, HeroChest, BlastYellow, BlastSparks));
				Out.Add(Cue(EJamFx::Dust, Event.Pos, 0.f, DustGrey, Event.Amount));
				break;
			case EJamEvent::Slam:
				Out.Add(Cue(EJamFx::Dust, Event.Pos, 0.f, DustGrey, Event.Amount));
				break;
			case EJamEvent::Deflected:
				Out.Add(Cue(EJamFx::Sparks, Event.Pos, HeroChest, FLinearColor::White, DeflectSparks));
				break;
			case EJamEvent::HealTaken:
				Out.Add(Cue(EJamFx::Cash, Event.Pos, 0.f, CashGreen, 1.f));
				break;
			case EJamEvent::UltimateSlash:
				Out.Add(Cue(EJamFx::Sparks, Event.Pos, HeroChest, UltimateMagenta, UltimateSparks));
				break;
			default:
				break;
		}
	}
}

EJamChargeLook JamFxRules::ChargeLook(const FJamLayers& Shown)
{
	// The aura belongs to the full art; the glow to the plain effects of the middle tier; greybox gets the bars back.
	if (Shown.bArt)
	{
		return EJamChargeLook::Aura;
	}
	return Shown.bEffects ? EJamChargeLook::Glow : EJamChargeLook::Bars;
}

FJamAura JamFxRules::Aura(float Meter, bool bOwns, bool bWindingUp)
{
	FJamAura Out;
	if (!bOwns)
	{
		return Out;
	}
	Out.bOn = true;
	const float Charge = FMath::Clamp(Meter, 0.f, 1.f);
	Out.bReady = bWindingUp || Charge >= 1.f;
	if (bWindingUp)
	{
		Out.Size = AuraWindUpSize;
		Out.Rate = AuraWindUpRate;
	}
	else if (Out.bReady)
	{
		Out.Size = AuraReadySize;
		Out.Rate = AuraReadyRate;
	}
	else
	{
		Out.Size = FMath::Lerp(AuraLeastSize, AuraChargedSize, Charge);
		Out.Rate = FMath::Lerp(AuraLeastRate, AuraChargedRate, Charge);
	}
	return Out;
}
#pragma once

#include "CoreMinimal.h"
#include "Sim/JamLayerRules.h"

#include "JamNeonRules.generated.h"

/**
 * Numbers of the neon look of the stand-ins. The values live in the [JamNeon] section of Config/DefaultGame.ini, one
 * line per field. Glow is the multiplier of the neon material: above 1 it blooms.
 */
USTRUCT()
struct JAMGAME_API FJamNeonSettings
{
	GENERATED_BODY()

	/** The tempo of the music the floor lines pulse to. */
	UPROPERTY()
	float Bpm = 0.f;

	/** The glow of the floor lines between beats, the extra glow on a beat, and how fast the extra dies (seconds). */
	UPROPERTY()
	float LineGlow = 0.f;

	UPROPERTY()
	float BeatPulse = 0.f;

	UPROPERTY()
	float BeatDecay = 0.f;

	/** The steady glow of the posts and of the ring at the edge of the arena. */
	UPROPERTY()
	float PostGlow = 0.f;

	UPROPERTY()
	float EdgeGlow = 0.f;

	/** The glow of the effects: blades, flashes, warnings. */
	UPROPERTY()
	float EffectGlow = 0.f;

	/** Bloom of the camera with the effects layer, and once the Publisher took it. */
	UPROPERTY()
	float Bloom = 0.f;

	UPROPERTY()
	float BloomCut = 0.f;
};

/**
 * The neon look: how bright the floor lines are at a moment of the music, and how much the camera blooms with the
 * layers the Publisher has left. Presentation only.
 * Tests: Jam.Neon.*
 */
namespace JamNeonRules
{
/** Section with the neon numbers (FJamNeonSettings). */
inline const TCHAR* const Section = TEXT("JamNeon");

/** The glow of the floor lines MusicTime seconds after the music started: a kick on every beat, then a fall. */
JAMGAME_API float LineGlow(float MusicTime, const FJamNeonSettings& Settings);

/** The bloom of the camera with these layers: the full look blooms, the cut effects take the bloom with them. */
JAMGAME_API float Bloom(const FJamLayers& Layers, const FJamNeonSettings& Settings);
} // namespace JamNeonRules
#include "View/JamNeonRules.h"

float JamNeonRules::LineGlow(float MusicTime, const FJamNeonSettings& Settings)
{
	if (Settings.Bpm <= 0.f || Settings.BeatDecay <= 0.f)
	{
		return Settings.LineGlow;
	}
	const float Beat = 60.f / Settings.Bpm;
	float SinceBeat = FMath::Fmod(FMath::Max(0.f, MusicTime), Beat);
	// A hair of float error short of a beat is the beat, not the tail of the one before.
	if (Beat - SinceBeat < KINDA_SMALL_NUMBER)
	{
		SinceBeat = 0.f;
	}
	return Settings.LineGlow + Settings.BeatPulse * FMath::Exp(-SinceBeat / Settings.BeatDecay);
}

float JamNeonRules::Bloom(const FJamLayers& Layers, const FJamNeonSettings& Settings)
{
	return Layers.bEffects ? Settings.Bloom : Settings.BloomCut;
}
#pragma once

#include "Core/JamTypes.h"
#include "CoreMinimal.h"
#include "GameFramework/Actor.h"

#include "JamFxView.generated.h"

class UNiagaraComponent;
class UNiagaraSystem;

/**
 * The rich effects of the full-art tier (T-069): Niagara sparks, dust and cash bursts on the events JamFxRules picks,
 * and the neon embers that drift over the arena while the art is whole. The first cut takes all of it; the plain
 * effects of AJamEffectsView stay.
 */
UCLASS()
class JAMGAME_API AJamFxView : public AActor
{
	GENERATED_BODY()

public:
	AJamFxView();

	/** Loads the systems and starts the embers over the arena. */
	void Init();

	/**
	 * Starts the effects of this frame's events while bArt; the embers run while bArt and fade when it goes. The
	 * Ultimate's charge aura (T-072) burns round the hero, standing at HeroAt, while bArt.
	 */
	void Sync(const FJamFight& Fight, TConstArrayView<FJamEvent> Events, bool bArt, const FVector& HeroAt);

private:
	UPROPERTY()
	TObjectPtr<UNiagaraSystem> Sparks;

	UPROPERTY()
	TObjectPtr<UNiagaraSystem> Dust;

	UPROPERTY()
	TObjectPtr<UNiagaraSystem> Cash;

	UPROPERTY()
	TObjectPtr<UNiagaraSystem> Embers;

	UPROPERTY()
	TObjectPtr<UNiagaraSystem> Charge;

	UPROPERTY()
	TObjectPtr<UNiagaraComponent> Ambient;

	UPROPERTY()
	TObjectPtr<UNiagaraComponent> ChargeAura;

	bool bAmbientOn = false;
	bool bChargeOn = false;
	bool bWasReady = false;

	/** Keeps the charge aura on the hero, sized by his meter, with a burst the moment it is full. */
	void SyncCharge(const FJamFight& Fight, bool bArt, const FVector& HeroAt);
};
#include "View/JamFxView.h"

#include "NiagaraComponent.h"
#include "NiagaraFunctionLibrary.h"
#include "NiagaraSystem.h"
#include "View/JamFxRules.h"

namespace
{
// The systems are made in the editor (Niagara toolset), loaded by path: /Game/FX is always cooked.
const TCHAR* const SparksPath = TEXT("/Game/FX/NS_JamHitSparks.NS_JamHitSparks");
const TCHAR* const DustPath = TEXT("/Game/FX/NS_JamSlamDust.NS_JamSlamDust");
const TCHAR* const CashPath = TEXT("/Game/FX/NS_JamCashBurst.NS_JamCashBurst");
const TCHAR* const EmbersPath = TEXT("/Game/FX/NS_JamEmbers.NS_JamEmbers");
const TCHAR* const ChargePath = TEXT("/Game/FX/NS_JamUltCharge.NS_JamUltCharge");
// The charge aura burns in the Ultimate's magenta; the burst when it is full comes off the chest.
const FLinearColor ChargeMagenta(1.0f, 0.3f, 0.85f);
constexpr float ChestHeight = 120.f;
constexpr float ReadyBurst = 1.6f;
// The dust and the cash start a little above the floor, under the warning circles' glow.
constexpr float GroundHeight = 5.f;
} // namespace

AJamFxView::AJamFxView()
{
	PrimaryActorTick.bCanEverTick = false;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));
}

void AJamFxView::Init()
{
	Sparks = LoadObject<UNiagaraSystem>(nullptr, SparksPath);
	Dust = LoadObject<UNiagaraSystem>(nullptr, DustPath);
	Cash = LoadObject<UNiagaraSystem>(nullptr, CashPath);
	Embers = LoadObject<UNiagaraSystem>(nullptr, EmbersPath);
	Charge = LoadObject<UNiagaraSystem>(nullptr, ChargePath);
	if (Charge)
	{
		ChargeAura = UNiagaraFunctionLibrary::SpawnSystemAttached(Charge, RootComponent, NAME_None, FVector::ZeroVector,
			FRotator::ZeroRotator, EAttachLocation::KeepRelativeOffset, false, false);
		ChargeAura->SetVariableLinearColor(TEXT("User.Color"), ChargeMagenta);
	}
	if (Embers)
	{
		Ambient = UNiagaraFunctionLibrary::SpawnSystemAttached(Embers, RootComponent, NAME_None, FVector::ZeroVector, FRotator::ZeroRotator,
			EAttachLocation::KeepRelativeOffset, false, false);
	}
}

void AJamFxView::SyncCharge(const FJamFight& Fight, bool bArt, const FVector& HeroAt)
{
	const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
	const FJamAura Aura =
		JamFxRules::Aura(Hero.Ultimate.Meter, Fight.Ledger.Has(EJamSide::Hero, EJamMechanic::Ultimate), Hero.Ultimate.bPending);
	const bool bOn = bArt && Aura.bOn;
	if (ChargeAura && bOn != bChargeOn)
	{
		bChargeOn = bOn;
		bOn ? ChargeAura->Activate(true) : ChargeAura->Deactivate();
	}
	if (ChargeAura && bOn)
	{
		ChargeAura->SetWorldLocation(HeroAt);
		ChargeAura->SetVariableFloat(TEXT("User.Size"), Aura.Size);
		ChargeAura->SetVariableFloat(TEXT("User.Rate"), Aura.Rate);
	}
	// The moment the meter fills: one burst off the chest, so "ready" is an event the eye catches, not a slow change.
	if (bOn && Aura.bReady && !bWasReady && Sparks)
	{
		if (UNiagaraComponent* Fx = UNiagaraFunctionLibrary::SpawnSystemAtLocation(this, Sparks, HeroAt + FVector(0.0, 0.0, ChestHeight)))
		{
			Fx->SetVariableLinearColor(TEXT("User.Color"), ChargeMagenta);
			Fx->SetVariableFloat(TEXT("User.Scale"), ReadyBurst);
		}
	}
	bWasReady = Aura.bReady;
}

void AJamFxView::Sync(const FJamFight& Fight, TConstArrayView<FJamEvent> Events, bool bArt, const FVector& HeroAt)
{
	SyncCharge(Fight, bArt, HeroAt);
	if (Ambient && bArt != bAmbientOn)
	{
		bAmbientOn = bArt;
		// Deactivate lets the embers in the air die out instead of vanishing with the cut.
		bArt ? Ambient->Activate(true) : Ambient->Deactivate();
	}
	TArray<FJamFxCue> Cues;
	JamFxRules::CuesFor(Fight, Events, bArt, Cues);
	for (const FJamFxCue& Cue : Cues)
	{
		UNiagaraSystem* System = Cue.Kind == EJamFx::Sparks ? Sparks.Get() : Cue.Kind == EJamFx::Dust ? Dust.Get() : Cash.Get();
		if (!System)
		{
			continue;
		}
		const float Height = Cue.Kind == EJamFx::Sparks ? Cue.Height : GroundHeight;
		UNiagaraComponent* Fx = UNiagaraFunctionLibrary::SpawnSystemAtLocation(this, System, FVector(Cue.Pos.X, Cue.Pos.Y, Height));
		if (!Fx)
		{
			continue;
		}
		Fx->SetVariableLinearColor(TEXT("User.Color"), Cue.Color);
		Fx->SetVariableFloat(Cue.Kind == EJamFx::Dust ? TEXT("User.Radius") : TEXT("User.Scale"), Cue.Size);
	}
}

