{
	static constexpr int32 Total = 6;

	/** The full art (T-067): the 3D hero and the rich effects. */
	bool bArt = true;
	bool bEffects = true;
	bool bMaterials = true;
	bool bAnimation = true;
	bool bModel = true;
	bool bHud = true;

