IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamFxAuraTest, "Jam.Fx.TheAuraGrowsWithTheChargeAndSaysReady", JamTest::Flags)

bool FJamFxAuraTest::RunTest(const FString& Parameters)
{
	TestFalse(TEXT("no aura before he owns the Ultimate"), JamFxRules::Aura(0.5f, false, false).bOn);
	const FJamAura Empty = JamFxRules::Aura(0.f, true, false);
	const FJamAura Half = JamFxRules::Aura(0.5f, true, false);
	const FJamAura Almost = JamFxRules::Aura(0.99f, true, false);
	const FJamAura Full = JamFxRules::Aura(1.f, true, false);
	const FJamAura WindUp = JamFxRules::Aura(1.f, true, true);
	TestTrue(TEXT("a faint aura from the start of the charge"), Empty.bOn && Empty.Size > 0.f && Empty.Rate > 0.f);
	TestTrue(TEXT("it grows with the charge"), Half.Size > Empty.Size && Almost.Size > Half.Size && Half.Rate > Empty.Rate);
	TestFalse(TEXT("not ready short of full"), Almost.bReady);
	TestTrue(TEXT("ready when full"), Full.bReady);
	TestTrue(TEXT("full is a clear step up, not one more percent"), Full.Size > 1.2f * Almost.Size && Full.Rate > 1.5f * Almost.Rate);
	TestTrue(TEXT("its biggest while he winds the cut up"), WindUp.Size > Full.Size && WindUp.Rate > Full.Rate);
	TestTrue(TEXT("an overfull meter reads as full"), FMath::IsNearlyEqual(JamFxRules::Aura(1.5f, true, false).Size, Full.Size));
	return true;
}

#endif // WITH_DEV_AUTOMATION_TESTS

