3	float JamNeonRules::LineGlow(float MusicTime, const FJamNeonSettings& Settings)
4	{
5		if (Settings.Bpm <= 0.f || Settings.BeatDecay <= 0.f)
6		{
7			return Settings.LineGlow;
8		}
9		const float Beat = 60.f / Settings.Bpm;
10		float SinceBeat = FMath::Fmod(FMath::Max(0.f, MusicTime), Beat);
11		// A hair of float error short of a beat is the beat, not the tail of the one before.
12		if (Beat - SinceBeat < KINDA_SMALL_NUMBER)
13		{
14			SinceBeat = 0.f;
15		}
16		return Settings.LineGlow + Settings.BeatPulse * FMath::Exp(-SinceBeat / Settings.BeatDecay);
17	}
