namespace
{
FJamNeonSettings TestNeon()
{
	FJamNeonSettings S;
	S.Bpm = 120.f;
	S.LineGlow = 2.f;
	S.BeatPulse = 3.f;
	S.BeatDecay = 0.1f;
	S.PostGlow = 4.f;
	S.EdgeGlow = 5.f;
	S.EffectGlow = 3.f;
	S.Bloom = 1.5f;
	S.BloomCut = 0.2f;
	return S;
}
