input.new_string:
Floor->SetRelativeLocation(FVector(0.0, 0.0, -0.5 * FloorThickness));
GlossFloor = LoadObject<UMaterialInterface>(nullptr, GlossFloorPath);
DressFloor();

for (int32 Index = 0; Index < PostCount; ++Index)
{
	const float Angle = UE_TWO_PI * Index / PostCount;
	const FVector2D Out(FMath::Cos(Angle), FMath::Sin(Angle));
	const FLinearColor Color = Index % 2 == 0 ? PostColorA : PostColorB;
	const FVector Location(ArenaRadius * Out.X, ArenaRadius * Out.Y, 0.5f * PostHeight);
	AddBox(Location, FMath::RadiansToDegrees(Angle), FVector(PostWidth, PostWidth, PostHeight), Color, EArenaPiece::Post);

	UPointLightComponent* Lamp = NewObject<UPointLightComponent>(this);
	Lamp->SetupAttachment(RootComponent);
	Lamp->SetMobility(EComponentMobility::Movable);
	// Sixteen shadowed lights would cost more than the whole fight; the neon only has to colour the floor.
	Lamp->SetCastShadows(false);
	Lamp->SetIntensityUnits(ELightUnits::Candelas);
	Lamp->SetIntensity(PostLightCandela);
	Lamp->SetAttenuationRadius(PostLightReach);
	Lamp->SetLightColor(Color);
	Lamp->SetVisibility(Light == EJamLight::Neon);
	Lamp->RegisterComponent();
	const float Inner = ArenaRadius - PostLightInset;
	Lamp->SetRelativeLocation(FVector(Inner * Out.X, Inner * Out.Y, PostLightHeight));
	PostLights.Add(Lamp);
}

