/**
 * The arena as the player sees it: a round floor with a grid to read movement by, posts along the edge to read
 * distance and turning by, and the light.
 * Built in code so that the map stays an empty file until the art arrives.
 */
UCLASS()
class JAMGAME_API AJamArenaView : public AActor
{
	GENERATED_BODY()

public:
	AJamArenaView();

	/** Sizes the floor, draws the grid, the edge band and the posts of an arena of this radius. Called once. */
	void Init(float ArenaRadius, const FJamNeonSettings& InNeon);

	/** The neon colours, or the engine's grey grid once the Publisher took the materials. Cheap when nothing changes. */
	void SetMaterials(bool bOn);

	/** The glow of the floor lines this frame (JamNeonRules::LineGlow); nothing while the grid is on. */
	void Pulse(float LineGlow);

	/**
	 * The light of a tier (T-077): the full art throws cyan and magenta neon light from the posts onto a glossy floor
	 * under a night sky; the shape ronin and the greybox get the plain sun on the plain floor. Cheap when nothing changes.
	 */
	void SetLight(EJamLight InLight);

private:
	/** The neon pieces: each kind glows by its own number. Lines and the edge are hidden on the grid, posts stay. */
	enum class EArenaPiece : uint8
	{
		Post,
		Line,
		Edge
	};

	/** A neon box with its centre at Location, turned by Yaw degrees. */
	void AddBox(const FVector& Location, float Yaw, const FVector& Size, const FLinearColor& Color, EArenaPiece Piece);

	/** Gives box Index the look of the materials now on: its neon, or the grid. */
	void Dress(int32 Index);

	float GlowOf(EArenaPiece Piece) const;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Floor;

	UPROPERTY()
	TObjectPtr<UDirectionalLightComponent> Sun;

	UPROPERTY()
	TObjectPtr<USkyAtmosphereComponent> Atmosphere;

	UPROPERTY()
	TObjectPtr<USkyLightComponent> SkyLight;

	UPROPERTY()
	TArray<TObjectPtr<UStaticMeshComponent>> Boxes;

	/** The neon light of the posts, one per post in its colour: on in the full-art tier only. */
	UPROPERTY()
	TArray<TObjectPtr<UPointLightComponent>> PostLights;

	/** The glossy floor of the full-art tier; the plain floor material when it is missing. */
	UPROPERTY()
	TObjectPtr<UMaterialInterface> GlossFloor;

	TArray<FLinearColor> BoxColors;
	TArray<EArenaPiece> Pieces;
	FJamNeonSettings Neon;
	bool bMaterials = true;
	EJamLight Light = EJamLight::Flat;

	/** Dresses the floor for the materials and the light now on. */
	void DressFloor();
};

