26	void AJamLightView::Init(float ArenaRadius)
27	{
28		const float Inner = ArenaRadius - LampInset;
29		for (int32 Index = 0; Index < LampCount; ++Index)
30		{
31			const float Angle = UE_TWO_PI * Index / LampCount;
32			UPointLightComponent* Lamp = NewObject<UPointLightComponent>(this);
33			Lamp->SetupAttachment(RootComponent);
34			Lamp->SetMobility(EComponentMobility::Movable);
35			// Sixteen shadowed lights would cost more than the whole fight; the neon only has to colour the scene.
36			Lamp->SetCastShadows(false);
37			Lamp->SetIntensityUnits(ELightUnits::Candelas);
38			Lamp->SetIntensity(LampCandela);
39			Lamp->SetAttenuationRadius(LampReach);
40			Lamp->SetSourceRadius(LampSize);
41			Lamp->SetLightColor(Index % 2 == 0 ? LampCyan : LampMagenta);
42			Lamp->SetVisibility(Light == EJamLight::Neon);
43			Lamp->RegisterComponent();
44			Lamp->SetRelativeLocation(FVector(Inner * FMath::Cos(Angle), Inner * FMath::Sin(Angle), LampHeight));
45			Lamps.Add(Lamp);
46		}
47	}
