49	void AJamLightView::SetLight(EJamLight InLight)
50	{
51		if (InLight == Light)
52		{
53			return;
54		}
55		Light = InLight;
56		for (UPointLightComponent* Lamp : Lamps)
57		{
58			Lamp->SetVisibility(Light == EJamLight::Neon);
59		}
